sysjobstep.command:
SET ANSI_NULLS, QUOTED_IDENTIFIER ON;

DECLARE @errorPK uniqueidentifier = NEWID();
DECLARE @source varchar(3) = 'SQL';
DECLARE @errorType varchar(3) = 'Fai';
DECLARE @inboxPK varchar(36) = NULL;
DECLARE @currentDateTimeUTC varchar(32) = convert(varchar(32), getutcdate(), 127);
DECLARE @issueMessageDelimiter nvarchar(50) = '
----------BIZTALK PROPERTIES----------
';

DECLARE @description nvarchar(max);
DECLARE @textData nvarchar(max);
DECLARE @graphXml xml;
DECLARE @issueManagerKey nvarchar(max);
DECLARE @clientAppName nvarchar(max);
DECLARE @hostname nvarchar(max);

SET @textData = REPLACE('$(ESCAPE_NONE(WMI(TextData)))', '&#x0A;', CHAR(10));
SET @graphXml = @textData

DECLARE @databaseName nvarchar(1000) = @graphXml.value('(/TextData/blocked-process-report/blocked-process/process/@currentdbname)[1]', 'nvarchar(1000)');
DECLARE @logMessage nvarchar(max) = 'Blocked Process in database [' + @databaseName + ']: ' + @textData;
DECLARE @pos int = 1, @len int = 1000;
WHILE @pos <= LEN(@logMessage) BEGIN PRINT SUBSTRING(@logMessage, @pos, @len); SET @pos += @len; END
IF @databaseName NOT IN ('BAMArchive','BAMPrimaryImport','BizTalkDTADb','BizTalkMgmtDb','BizTalkMsgBoxDb','SSISDB','SSODB')
  RETURN;

SELECT @issueManagerKey = @graphXml.value('(/TextData/blocked-process-report/blocked-process/process/inputbuf)[string-length()>0][1]', 'nvarchar(max)');

IF @issueManagerKey IS NULL
BEGIN
	SET @clientAppName = @graphXml.value('(/TextData/blocked-process-report/blocked-process/process/@clientapp)[1]', 'nvarchar(max)');
	SET @hostname = @graphXml.value('(/TextData/blocked-process-report/blocked-process/process/@hostname)[1]', 'nvarchar(max)');
	SET @issueManagerKey = CONCAT(@clientAppName, '-', @hostname);
END

IF @issueManagerKey = '-'
BEGIN
	SET @issueManagerKey = @graphXml.value('(/TextData/blocked-process-report/blocking-process/process/inputbuf)[string-length()>0][1]', 'nvarchar(max)');
END

IF @issueManagerKey IS NULL
BEGIN
	SET @clientAppName = @graphXml.value('(/TextData/blocked-process-report/blocking-process/process/@clientapp)[1]', 'nvarchar(max)');
	SET @hostname = @graphXml.value('(/TextData/blocked-process-report/blocking-process/process/@hostname)[1]', 'nvarchar(max)');
	SET @issueManagerKey = CONCAT(@clientAppName, '-', @hostname);
END

SET @issueManagerKey = REPLACE(CONCAT('Blocked process: ', @issueManagerKey), CHAR(10), ' ')
WHILE CHARINDEX('  ', @issueManagerKey) > 0 SET @issueManagerKey = REPLACE(@issueManagerKey, '  ', ' ')
SET @description = CONCAT(@issueManagerKey, @issueMessageDelimiter, 'SERVERNAME: $(ESCAPE_NONE(A-SVR))', CHAR(10), 'REPORT:', CHAR(10),  @textData);

EXECUTE [eHubTransactionsServer].[eHubTransactions].[dbo].[InsertError] 
	 @ErrorPK = @errorPK
	,@Source = @source
	,@ErrorType = @errorType
	,@Description = @description
	,@InboxPK = @inboxPK
	,@CurrentDateTimeUTC = @currentDateTimeUTC;

PRINT 'Sent to issue manager.'
